CREATE COLUMN TABLE "TEST_AP"."OUOM" ("UomEntry" INTEGER CS_INT NOT NULL , "UomCode" NVARCHAR(20) NOT NULL , "UomName" NVARCHAR(100), "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" SMALLINT CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "CreateDate" LONGDATE CS_LONGDATE, "Length1" DECIMAL(21,6) CS_FIXED, "Len1Unit" SMALLINT CS_INT, "length2" DECIMAL(21,6) CS_FIXED, "Len2Unit" SMALLINT CS_INT, "Width1" DECIMAL(21,6) CS_FIXED, "Wdth1Unit" SMALLINT CS_INT, "Width2" DECIMAL(21,6) CS_FIXED, "Wdth2Unit" SMALLINT CS_INT, "Height1" DECIMAL(21,6) CS_FIXED, "Hght1Unit" SMALLINT CS_INT, "Height2" DECIMAL(21,6) CS_FIXED, "Hght2Unit" SMALLINT CS_INT, "Volume" DECIMAL(21,6) CS_FIXED, "VolUnit" SMALLINT CS_INT, "Weight1" DECIMAL(21,6) CS_FIXED, "WghtUnit" SMALLINT CS_INT, "Weight2" DECIMAL(21,6) CS_FIXED, "Wght2Unit" SMALLINT CS_INT, "IntSymbol" NVARCHAR(20), "EwbUnit" INTEGER CS_INT, PRIMARY KEY ("UomEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OUOM_CODE" ON "TEST_AP"."OUOM" ( "UomCode" ASC );
CREATE INDEX "OUOM_NAME" ON "TEST_AP"."OUOM" ( "UomName" ASC )